recordedFiles.check.sh:
#!/bin/bash
set -eu
case "$1" in
  red)
    exec node node_modules/vitest/vitest.mjs run apps/cli/test/uninstall.test.ts --pool=forks --maxWorkers=1 -t 'browser ownership gives safe guidance and preserves all fixture state' --reporter=json --outputFile=/evidence/red.json
    ;;
  green)
    exec node node_modules/vitest/vitest.mjs run apps/cli/test/uninstall.test.ts --pool=forks --maxWorkers=1 --reporter=json --outputFile=/evidence/green.json
    ;;
  types)
    exec node node_modules/typescript/bin/tsc --noEmit --incremental false
    ;;
  lint)
    exec node_modules/.bin/biome check apps/cli/src/commands/uninstall.ts apps/cli/test/uninstall.test.ts
    ;;
  *) exit 2 ;;
esac
